// Spring Boot - Remove server version from response headers
// application.properties or application.yml

# Hide server version in response header
server.server-header=
# Or customize to generic value
# server.server-header=WebServer

# Disable error details in production
server.error.include-message=never
server.error.include-binding-errors=never
server.error.include-stacktrace=never
server.error.include-exception=false

# Custom error pages
server.error.whitelabel.enabled=false

# Create custom error controller
import org.springframework.boot.web.servlet.error.ErrorController;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.RequestMapping;
import javax.servlet.http.HttpServletRequest;

@Controller
public class CustomErrorController implements ErrorController {

    @RequestMapping("/error")
    public String handleError(HttpServletRequest request) {
        Integer statusCode = (Integer) request.getAttribute("javax.servlet.error.status_code");

        if (statusCode == 404) {
            return "error/404";
        } else if (statusCode == 403) {
            return "error/403";
        } else if (statusCode == 500) {
            return "error/500";
        }

        return "error/generic";
    }
}

// Remove server header completely via filter
import javax.servlet.*;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

@Component
public class ServerHeaderFilter implements Filter {

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, 
                        FilterChain chain) throws IOException, ServletException {
        HttpServletResponse httpResponse = (HttpServletResponse) response;

        // Remove or obfuscate Server header
        httpResponse.setHeader("Server", "");

        chain.doFilter(request, response);
    }
}

// Disable banner in logs (optional)
spring.main.banner-mode=off

