// JUnit test to verify server header removed
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
public class ServerHardeningTest {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void serverHeaderShouldBeEmpty() throws Exception {
        mockMvc.perform(get("/"))
            .andExpect(status().isOk())
            .andExpect(result -> {
                String serverHeader = result.getResponse().getHeader("Server");
                assertTrue(serverHeader == null || serverHeader.isEmpty() || 
                          !serverHeader.contains("Spring") && !serverHeader.contains("Tomcat"),
                    "Server header should not reveal version information");
            });
    }

    @Test
    public void errorPagesShouldNotRevealFramework() throws Exception {
        mockMvc.perform(get("/nonexistent"))
            .andExpect(status().isNotFound())
            .andExpect(result -> {
                String content = result.getResponse().getContentAsString();
                assertFalse(content.contains("Whitelabel Error Page"),
                    "Should not show default Spring error page");
                assertFalse(content.contains("Tomcat"),
                    "Should not reveal Tomcat in error pages");
                assertFalse(content.contains("Spring"),
                    "Should not reveal Spring in error pages");
            });
    }

    @Test
    public void errorShouldNotIncludeStackTrace() throws Exception {
        mockMvc.perform(get("/error-endpoint"))
            .andExpect(result -> {
                String content = result.getResponse().getContentAsString();
                assertFalse(content.contains(".java:"),
                    "Should not expose stack traces");
                assertFalse(content.contains("Exception"),
                    "Should not expose exception details");
            });
    }
}

