// Express.js - Remove server version and harden configuration
const express = require('express');
const helmet = require('helmet');
const path = require('path');

const app = express();

// Use helmet to remove X-Powered-By and set security headers
app.use(helmet());

// Alternative: Manually remove X-Powered-By
app.disable('x-powered-by');

// Custom Server header (or remove completely)
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  res.setHeader('Server', ''); // Empty or generic: 'WebServer'
  next();
});

// Disable directory listing (Express doesn't enable by default, but verify)
// Never use express.static without proper configuration
app.use('/public', express.static(path.join(__dirname, 'public'), {
  dotfiles: 'deny',
  index: false, // Disable directory index
}));

// Custom error handlers - DO NOT expose stack traces in production
if (process.env.NODE_ENV === 'production') {
  // Production error handler - no stack traces
  app.use((err, req, res, next) => {
    res.status(err.status || 500);
    res.json({
      error: 'An error occurred processing your request',
      // DO NOT include: err.message, err.stack
    });
  });
} else {
  // Development error handler - with stack traces
  app.use((err, req, res, next) => {
    res.status(err.status || 500);
    res.json({
      error: err.message,
      stack: err.stack
    });
  });
}

// Custom 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found'
    // DO NOT include: requested path, server info
  });
});

// Remove unnecessary response headers
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  res.removeHeader('X-AspNet-Version');
  res.removeHeader('X-AspNetMvc-Version');
  next();
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

