// Mocha/Chai test for server hardening
const request = require('supertest');
const { expect } = require('chai');
const app = require('../app');

describe('Server Hardening Tests', () => {
  it('should not expose X-Powered-By header', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        expect(res.headers).to.not.have.property('x-powered-by');
        done();
      });
  });

  it('should not expose Server version information', (done) => {
    request(app)
      .get('/')
      .end((err, res) => {
        if (err) return done(err);

        const serverHeader = res.headers['server'];
        if (serverHeader) {
          expect(serverHeader).to.not.match(/express/i);
          expect(serverHeader).to.not.match(/node/i);
          expect(serverHeader).to.not.include('/');
        }

        done();
      });
  });

  it('should not expose stack traces in error responses', (done) => {
    request(app)
      .get('/trigger-error') // endpoint that throws error
      .expect(500)
      .end((err, res) => {
        if (err) return done(err);

        const body = JSON.stringify(res.body);
        expect(body).to.not.include('.js:');
        expect(body).to.not.include('at ');
        expect(body).to.not.match(/node_modules/i);

        done();
      });
  });

  it('should not allow directory listing', (done) => {
    request(app)
      .get('/public/')
      .end((err, res) => {
        if (err) return done(err);

        // Should either 404 or serve index.html, not directory listing
        expect(res.status).to.be.oneOf([404, 200]);
        if (res.status === 200) {
          expect(res.text).to.not.include('Index of');
          expect(res.text).to.not.include('Parent Directory');
        }

        done();
      });
  });

  it('custom 404 should not reveal server information', (done) => {
    request(app)
      .get('/nonexistent')
      .expect(404)
      .end((err, res) => {
        if (err) return done(err);

        const body = JSON.stringify(res.body);
        expect(body).to.not.match(/express/i);
        expect(body).to.not.match(/node/i);
        expect(body).to.not.include(process.cwd());

        done();
      });
  });
});

