# Nginx Server Hardening Configuration
# /etc/nginx/nginx.conf or /etc/nginx/sites-available/your-site

# Hide Nginx version in Server header and error pages
server_tokens off;

# Disable directory listing globally
autoindex off;

http {
    # Hide Nginx version
    server_tokens off;

    # Custom Server header (optional - or leave empty)
    more_set_headers 'Server: WebServer';
    # Or remove completely:
    # more_clear_headers 'Server';

    # Disable autoindex globally
    autoindex off;

    # Custom error pages
    error_page 400 401 402 403 404 /error.html;
    error_page 500 502 503 504 /error.html;

    server {
        listen 443 ssl http2;
        server_name your-domain.com;

        # Root directory
        root /var/www/html;

        # Disable directory listing for this server block
        autoindex off;

        # Custom error pages location
        location = /error.html {
            internal;
            root /var/www/error-pages;
        }

        # Deny access to hidden files
        location ~ /\. {
            deny all;
            access_log off;
            log_not_found off;
        }

        # Deny access to backup files
        location ~ ~$ {
            deny all;
            access_log off;
            log_not_found off;
        }

        # Disable .git directory access
        location ~ /\.git {
            deny all;
        }

        # Remove server status pages
        # Comment out or remove these if enabled:
        # location /nginx_status { stub_status on; }

        # Security headers
        add_header X-Frame-Options "DENY" always;
        add_header X-Content-Type-Options "nosniff" always;
        add_header X-XSS-Protection "1; mode=block" always;

        # Rest of your configuration
        location / {
            try_files $uri $uri/ =404;
        }
    }
}

