// Selenium test for server hardening validation
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.testng.annotations.Test;
import org.testng.Assert;
import java.io.IOException;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.List;
import java.util.Map;

public class ServerHardeningTest {

    @Test
    public void verifyServerHeaderObfuscated() throws IOException {
        URL url = new URL("https://your-domain.com");
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("HEAD");

        Map<String, List<String>> headers = connection.getHeaderFields();

        // Check Server header
        List<String> serverHeader = headers.get("Server");
        if (serverHeader != null && !serverHeader.isEmpty()) {
            String serverValue = serverHeader.get(0);

            // Should not contain version numbers
            Assert.assertFalse(serverValue.matches(".*\\d+\\.\\d+.*"),
                "Server header should not contain version numbers: " + serverValue);

            // Should not contain specific server names with versions
            Assert.assertFalse(serverValue.contains("Apache/"),
                "Server header reveals Apache version");
            Assert.assertFalse(serverValue.contains("nginx/"),
                "Server header reveals nginx version");
            Assert.assertFalse(serverValue.contains("Microsoft-IIS/"),
                "Server header reveals IIS version");
        }

        connection.disconnect();
    }

    @Test
    public void verifyNoPoweredByHeader() throws IOException {
        URL url = new URL("https://your-domain.com");
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
        connection.setRequestMethod("HEAD");

        Map<String, List<String>> headers = connection.getHeaderFields();

        // Check X-Powered-By is not present
        Assert.assertNull(headers.get("X-Powered-By"),
            "X-Powered-By header should not be present");

        Assert.assertNull(headers.get("X-AspNet-Version"),
            "X-AspNet-Version header should not be present");

        Assert.assertNull(headers.get("X-AspNetMvc-Version"),
            "X-AspNetMvc-Version header should not be present");

        connection.disconnect();
    }

    @Test
    public void verifyDirectoryListingDisabled() throws IOException {
        String[] testPaths = {
            "https://your-domain.com/images/",
            "https://your-domain.com/assets/",
            "https://your-domain.com/static/",
            "https://your-domain.com/uploads/"
        };

        for (String testUrl : testPaths) {
            URL url = new URL(testUrl);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setInstanceFollowRedirects(false);

            int responseCode = connection.getResponseCode();

            // Should be 403 or 404, not 200
            Assert.assertTrue(responseCode == 403 || responseCode == 404,
                "Directory listing should be disabled for " + testUrl + 
                ". Got response code: " + responseCode);

            connection.disconnect();
        }
    }

    @Test
    public void verifyCustomErrorPages() throws IOException {
        // Test 404
        URL url = new URL("https://your-domain.com/nonexistent-page-12345");
        HttpURLConnection connection = (HttpURLConnection) url.openConnection();

        int responseCode = connection.getResponseCode();
        Assert.assertEquals(responseCode, 404, "Should return 404 for nonexistent page");

        // Read response body
        java.io.InputStream is = connection.getErrorStream();
        java.util.Scanner scanner = new java.util.Scanner(is).useDelimiter("\\A");
        String responseBody = scanner.hasNext() ? scanner.next() : "";

        // Verify custom error page (not default server error)
        Assert.assertFalse(responseBody.contains("Apache"),
            "Error page should not contain 'Apache'");
        Assert.assertFalse(responseBody.contains("nginx"),
            "Error page should not contain 'nginx'");
        Assert.assertFalse(responseBody.contains("Microsoft"),
            "Error page should not contain 'Microsoft'");
        Assert.assertFalse(responseBody.contains("Tomcat"),
            "Error page should not contain 'Tomcat'");

        connection.disconnect();
    }

